function latest_line(    path, parts, count, key, value) {
  if ($0 !~ /^body\.(message\.)?usage\./) return
  path = $0; sub(/:[[:space:]]*.*/, "", path)
  count = split(path, parts, "[.]"); if (count < 3) return
  key = parts[count]; value = $0; sub(/^.*:[[:space:]]*/, "", value)
  if (value !~ /^-?[0-9]+$/) return
  values[key] = value + 0; any = 1
}
function compact(n,    unit, units) {
  unit = 0; units = " KMGTP"; n = int(n < 0 ? 0 : n)
  while (n >= 1000 && unit < 5) { n = int(n / 1000); unit++ }
  return sprintf("%d%s", n % 10000, unit ? substr(units, unit + 1, 1) : "")
}
function cache_block(percent, cached, blocks, idx) {
  if (cached <= 0) return "_"
  split("▁ ▂ ▃ ▄ ▅ ▆ ▇", blocks, " "); idx = int(percent * 7 / 100)
  if (idx < 0) idx = 0; if (idx > 6) idx = 6
  return blocks[idx + 1]
}
{ latest_line() }
END {
  if (!any) exit
  input = values["input_tokens"] + values["cache_read_input_tokens"] + values["cache_creation_input_tokens"]
  output = values["output_tokens"]; cached = values["cache_read_input_tokens"]; written = values["cache_creation_input_tokens"]
  percent = input > 0 ? int(cached * 100 / input) : 0
  printf "::stats::✥%s%s%s::", compact(output), cache_block(percent, cached), compact(input)
  printf "%d in, %d cached (%d%%)", input, cached, percent
  if (written > 0) printf ", %d written", written
  printf ", %d out\n", output
}
